def gen(rng):
    def fmt(a, b):
        return '%d %d\n%s\n%s' % (len(a), len(b), ' '.join(map(str, a)), ' '.join(map(str, b)))
    tests = [
        fmt([1], [2]), fmt([5], [1]), fmt([3, 3, 3], [3, 3]), fmt([1, 2, 3], [4, 5, 6]),
        fmt([4, 5, 6], [1, 2, 3]), fmt([-5, 0, 7], [-6, -5, 100, 200]), fmt([1], [1]),
        fmt([1, 1, 1, 1], [1]),
    ]
    for n in (1, 2, 3, 5, 8, 12):
        for m in (1, 2, 4, 9, 15):
            a = sorted(rng.randint(-10, 10) for _ in range(n))
            b = sorted(rng.randint(-10, 10) for _ in range(m))
            tests.append(fmt(a, b))
    N = 100000
    tests.append(fmt(sorted(rng.randint(-10**9, 10**9) for _ in range(N)), sorted(rng.randint(-10**9, 10**9) for _ in range(N))))
    tests.append(fmt([2 * i for i in range(N)], [2 * i + 1 for i in range(N)]))
    tests.append(fmt(sorted(rng.randint(5 * 10**8, 10**9) for _ in range(N)), sorted(rng.randint(-10**9, 0) for _ in range(N))))
    return tests
